#!/usr/bin/env python3
import argparse
import csv
import json
import sys
from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP


def parse_timestamp(ts: str) -> datetime:
    """Parse an ISO8601 timestamp with optional UTC offset into a datetime object.
    datetime.fromisoformat handles offsets in Python 3.7+.
    """
    try:
        # fromisoformat can parse strings like '2023-01-01T12:00:00+02:00'
        return datetime.fromisoformat(ts)
    except ValueError:
        # Fallback: try stripping whitespace
        return datetime.fromisoformat(ts.strip())


def reconcile(input_file: str):
    # Mapping from tx_id to (timestamp, row) keeping the latest timestamp
    latest_transactions = {}

    with open(input_file, "r", newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            tx_id = row.get("tx_id")
            if tx_id is None:
                continue
            ts_str = row.get("timestamp", "")
            try:
                ts = parse_timestamp(ts_str)
            except Exception:
                # If timestamp cannot be parsed, treat it as earliest possible
                ts = datetime.min
            # If we have not seen this tx_id or this row is newer, store it
            if (tx_id not in latest_transactions) or (ts > latest_transactions[tx_id][0]):
                latest_transactions[tx_id] = (ts, row)

    total_valid_amount = Decimal('0')
    valid_count = 0
    failed_count = 0

    for _, row in latest_transactions.values():
        status = row.get("status", "").strip().upper()
        if status == "VALID":
            amount_str = row.get("amount", "0").strip()
            try:
                amount = Decimal(amount_str)
            except Exception:
                amount = Decimal('0')
            total_valid_amount += amount
            valid_count += 1
        else:
            failed_count += 1

    # Round to two decimal places using ROUND_HALF_UP
    total_valid_amount = total_valid_amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

    return {
        "total_valid_amount": float(total_valid_amount),
        "valid_count": valid_count,
        "failed_count": failed_count,
    }


def main():
    parser = argparse.ArgumentParser(description="Payment transaction reconciliation")
    parser.add_argument("--input", required=True, help="Path to the transactions CSV file")
    args = parser.parse_args()

    try:
        result = reconcile(args.input)
        print(json.dumps(result, indent=2))
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()
